/**
 * Returns the daily verse based on the day of the year (0-365).
 */
export function getDailyVerse(date: Date = new Date()): DailyVerse {
  const startOfYear = new Date(date.getFullYear(), 0, 1);
  const diff = date.getTime() - startOfYear.getTime();
  const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));
  const safeIndex = Math.abs(dayOfYear) % DAILY_VERSES.length;
  return DAILY_VERSES[safeIndex];
}
